function ResponsivePreviewCamera() {
  const { camera, size } = useThree()

  useLayoutEffect(() => {
    if (!(camera instanceof PerspectiveCamera)) return

    const aspect = size.width / Math.max(1, size.height)
    const operatorFocused = size.height < 360 || aspect < 1.55
    // Both framings sit on x = 0. The lobby grid leaves its middle column
    // empty for the operative, so an off-centre camera would put them behind
    // the panel instead of in the gap.
    if (operatorFocused) {
      // The small inset on the arsenal tab: a portrait, close in.
      camera.position.set(0, 1.32, 2.45)
      camera.lookAt(0, 0.78, 0.2)
    } else {
      // Full-bleed. At fov 38 and z 4.5 the ~1.75u operative fills a little
      // over half the frame height, leaving the deck and the near props to
      // read as a set rather than a backdrop.
      camera.position.set(0, 1.85, 4.5)
      camera.lookAt(0, 1.02, -0.2)
    }
    camera.updateProjectionMatrix()
  }, [camera, size.height, size.width])

  return null
}

