/**
 * Centred on the origin, which puts the operative on the floor ring the scene
 * already draws there. The UI frame leaves this column empty for exactly this
 * silhouette.
 */
function PreviewHero({ loadout }: { loadout: EquipmentLoadout }) {
  const motionRef = useRef<CharacterMotionState>({
    motion: 'idle',
    revision: 0,
  })
  const tint = useMemo(() => {
    if (loadout.armor === 'graveplate') return '#3b3b43'
    if (loadout.armor === 'veilweave-coat') return '#ededf1'
    return '#777780'
  }, [loadout.armor])
  return (
    // Turned to face the camera. The character model applies its own
    // π flip so the model's forward is world −Z, the game's convention — and
    // both lobby framings sit at +Z, so without this the operative presents
    // their back to the player on the screen that is meant to introduce them.
    <group position={[0, 0, 0.35]} rotation={[0, Math.PI, 0]}>
      <AssetBoundary
        fallback={<PreviewFallback tint={tint} />}
        resetKey="lobby-hero"
      >
        <EmbeddedDirectionalCharacterModel
          name="lobby-hero"
          url={assetUrl(PLAYER_VISUAL.model)}
          motionRef={motionRef}
          clips={LOBBY_PLAYER_CLIPS}
          position={[0, 0.02, 0]}
          rotation={[0, 0, 0]}
          scale={0.84 * PLAYER_VISUAL.scale}
          tint={tint}
          tintStrength={0.12}
          outline={PLAYER_VISUAL.outline}
          outlineDistance={PLAYER_VISUAL.outlineDistance}
        />
      </AssetBoundary>
    </group>
  )
}

function FrozenLobbyEnemy({
  position,
  rotation,
  model,
  scale = 0.48,
}: {
  position: [number, number, number]
  rotation: [number, number, number]
  model: 'maintenance' | 'sentry' | 'breach'
  scale?: number
}) {
  const motionRef = useRef<CharacterMotionState>({
    motion: 'idle',
    revision: 0,
  })
  // The deck displays the same chassis the arena spawns, so the lobby is a
  // preview rather than a museum of retired models.
  const visual = getEnemyDroneVisual(
    model === 'maintenance'
      ? 'grave-husk'
      : model === 'sentry'
        ? 'bone-archer'
        : 'crypt-brute',
  )

  return (
    <AssetBoundary
      fallback={null}
      resetKey={`lobby-${model}-${position.join('-')}`}
    >
      <SelfAnimatedModel
        name="lobby-frozen-enemy"
        url={assetUrl(visual.model)}
        motionRef={motionRef}
        clips={visual.clips}
        frozen
        tint="#2b3033"
        tintStrength={0.62}
        position={[
          position[0],
          position[1] + visual.verticalOffset * scale,
          position[2],
        ]}
        rotation={rotation}
        scale={scale * visual.scale}
        outlineDistance={visual.outlineDistance}
      />
    </AssetBoundary>
  )
}

function DungeonProp({
  asset,
  position,
  rotation = [0, 0, 0],
  scale = 1,
  tint = '#55555e',
}: {
  asset: 'wall' | 'column' | 'console' | 'crate' | 'beacon'
  position: [number, number, number]
  rotation?: [number, number, number]
  scale?: number | [number, number, number]
  tint?: string
}) {
  return (
    <group position={position} rotation={rotation} scale={scale}>
      <mesh castShadow receiveShadow>
        {asset === 'column' ? (
          <cylinderGeometry args={[0.24, 0.34, 1.8, 8]} />
        ) : asset === 'beacon' ? (
          <cylinderGeometry args={[0.08, 0.12, 1.1, 8]} />
        ) : (
          <boxGeometry
            args={
              asset === 'wall'
                ? [1.9, 2.2, 0.26]
                : asset === 'console'
                  ? [1.2, 0.72, 0.55]
                  : [0.72, 0.72, 0.72]
            }
          />
        )}
        <meshStandardMaterial color={tint} roughness={0.7} metalness={0.3} />
      </mesh>
      <mesh
        position={[
          0,
          asset === 'wall' ? 0.55 : asset === 'beacon' ? 0.55 : 0.18,
          asset === 'wall' ? 0.145 : -0.31,
        ]}
      >
        <boxGeometry args={[asset === 'wall' ? 1.25 : 0.34, 0.055, 0.035]} />
        <meshBasicMaterial color={TOON_PALETTE.cyan} toneMapped={false} />
      </mesh>
    </group>
  )
}

