export function LobbyPreview({ loadout }: { loadout: EquipmentLoadout }) {
  return (
    <div
      className="stillseen-lobby-render"
      data-preview-layout="responsive"
      data-testid="lobby-render"
    >
      <Canvas
        shadows="percentage"
        dpr={[1, 1.35]}
        // Matches ResponsivePreviewCamera's wide branch. Without that, the
        // very first frame renders from the old off-centre pose and snaps.
        camera={{ position: [0, 1.85, 4.5], fov: 38, near: 0.1, far: 30 }}
        gl={{
          antialias: true,
          powerPreference: 'high-performance',
          alpha: false,
        }}
        onCreated={({ camera, gl }) => {
          gl.outputColorSpace = SRGBColorSpace
          gl.toneMapping = ACESFilmicToneMapping
          gl.toneMappingExposure = 0.88
          camera.lookAt(0, 1.02, -0.2)
        }}
      >
        <ResponsivePreviewCamera />
        <Suspense fallback={null}>
          <PreviewScene loadout={loadout} />
        </Suspense>
      </Canvas>
    </div>
  )
}
